<?php
if(!defined('ABSPATH'))exit; final class DSVS_Parser{private static function xp($h){$d=new DOMDocument();libxml_use_internal_errors(true);$d->loadHTML('<?xml encoding="UTF-8">'.$h);libxml_clear_errors();return new DOMXPath($d);}private static function cells($xp,$tr){$a=array();foreach($xp->query('./th|./td',$tr)as$c){$v=trim(preg_replace('/\s+/u',' ',$c->textContent));if($v!=='')$a[]=$v;}return$a;}public static function standings($h){$xp=self::xp($h);foreach($xp->query('//table')as$t){if(stripos($t->textContent,'Mannschaft')===false||stripos($t->textContent,'Partien')===false)continue;$r=array();foreach($xp->query('.//tr',$t)as$tr){$c=self::cells($xp,$tr);if(count($c)>=9&&ctype_digit($c[0]))$r[]=array_slice($c,0,9);}if($r)return$r;}return array();}private static function games($h,$current){$xp=self::xp($h);$o=array();foreach($xp->query('//table')as$t){$is=stripos($t->textContent,'AKTUELLE ERGEBNISSE')!==false;if($current!==$is)continue;foreach($xp->query('.//tr',$t)as$tr){$c=self::cells($xp,$tr);$di=false;foreach($c as$i=>$v)if(preg_match('/(\d{2}\.\d{2}\.\d{4}).*?(\d{2}:\d{2})/',$v,$m)){$di=$i;break;}if($di===false)continue;$a=array_slice($c,$di+1);foreach($a as$i=>$v)if(preg_match('/^(\d+\s*:\s*\d+|:)$/',$v)&&$i>0&&isset($a[$i+1])){$dt=DateTime::createFromFormat('!d.m.Y H:i',$m[1].' '.$m[2],wp_timezone());$o[]=array('date'=>$m[1],'time'=>$m[2],'timestamp'=>$dt?$dt->getTimestamp():0,'home'=>$a[$i-1],'result'=>preg_replace('/\s+/','',$v),'away'=>$a[$i+1]);break;}}}return$o;}public static function current_games($h){return self::games($h,true);}public static function schedule($h){$g=self::games($h,false);usort($g,function($a,$b){return$a['timestamp']<=>$b['timestamp'];});return$g;}public static function owned($x){foreach(DSVS_TEAMS as$t)if(!strcasecmp($x,$t))return true;return false;}public static function upcoming($g,$n){$now=current_time('timestamp');$g=array_values(array_filter($g,function($x)use($now){return$x['timestamp']>=$now&&$x['result']===':'&&(self::owned($x['home'])||self::owned($x['away']));}));return array_slice($g,0,max(1,$n));}}
